def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    pos = [None] * (n * n)
    for r in range(n):
        for c in range(n):
            pos[int(data[1 + r * n + c])] = (r, c)
    ok = pos[0] == (0, 0)
    if ok:
        for k in range(n * n - 1):
            dr = abs(pos[k][0] - pos[k + 1][0])
            dc = abs(pos[k][1] - pos[k + 1][1])
            if dr * dc != 2:
                ok = False
                break
    print("true" if ok else "false")

