import sys

data = sys.stdin.read().split()
n = int(data[0])
g = [[int(data[1 + r * n + c]) for c in range(n)] for r in range(n)]

def find(v):
    for r in range(n):
        for c in range(n):
            if g[r][c] == v:
                return r, c

ok = g[0][0] == 0
for k in range(n * n - 1):
    r1, c1 = find(k)
    r2, c2 = find(k + 1)
    if (abs(r1 - r2), abs(c1 - c2)) not in ((1, 2), (2, 1)):
        ok = False
print("true" if ok else "false")

